class CoherenceThresholds:
    # System Stability Thresholds
    CPU_LOAD_WARNING = 80.0     # Percentage
    MEMORY_USAGE_WARNING = 85.0 # Percentage
    DISK_SPACE_WARNING = 90.0   # Percentage

    # Agent Health Thresholds
